function openCamera(id){const c=cameras.find(x=>x.id===id);if(!c)return;if(c.is_free){toast('Canal livre. Desmarque a opção para ativar o vídeo e o monitoramento.');return;}selected=id;page('map');$('viewer').hidden=false;$('viewer-title').textContent=c.name;$('viewer-status').innerHTML='<i class="dot '+(c.status==='online'?'online':c.status==='offline'?'offline':'unknown')+'"></i>';$('viewer-status').setAttribute('aria-label',names[c.status]||'Não verificada');$('viewer-status').title=names[c.status]||'Não verificada';renderCameraDetails(c);$('video-title').textContent=c.status==='online'?'Prévia do player':names[c.status];$('video-message').textContent=c.status==='online'?'Conectando ao stream cadastrado.':c.status==='offline'?'Falha de comunicação.':'Aguardando verificação de conexão.';if(map)map.panTo([c.lat,c.lng]);render();startLive(id);}
