function stopLive(notify=true){playGeneration++;activeLiveTicket=null;lastLiveConfirmation=0;liveReceivingId=null;lastVideoProgress=0;lastVideoTime=-1;if(notify&&authToken)fetch('/api/live-cancel',{method:'POST',headers:{Authorization:'Bearer '+authToken,'X-Video-Client':videoClientKey},keepalive:true}).catch(()=>{});if(liveAbort){liveAbort.abort();liveAbort=null;}if(hls){hls.destroy();hls=null;}const v=$('live-video');v.pause();v.removeAttribute('src');v.load();v.hidden=true;$('player-text').hidden=false;}
async function startLive(id){stopLive(false);const generation=playGeneration;$('video-title').textContent='Conectando ao canal…';$('video-message').textContent='O primeiro carregamento pode levar alguns segundos.';try{const result=await openReadyLive(id,generation);if(generation!==playGeneration)return;activeLiveTicket=result.url.split('/')[3];const v=$('live-video');if(typeof Hls!=='undefined'&&Hls.isSupported()){hls=new Hls({manifestLoadingTimeOut:30000,manifestLoadingMaxRetry:4,manifestLoadingRetryDelay:2000,levelLoadingTimeOut:30000,fragLoadingTimeOut:30000});hls.loadSource(result.url);hls.attachMedia(v);hls.on(Hls.Events.MANIFEST_PARSED,()=>{if(generation!==playGeneration)return;v.hidden=false;$('player-text').hidden=true;v.play().catch(()=>{});});let mediaRecovery=false;hls.on(Hls.Events.ERROR,(_,data)=>{if(data.fatal&&generation===playGeneration){if(data.type===Hls.ErrorTypes.MEDIA_ERROR&&!mediaRecovery){mediaRecovery=true;hls.recoverMediaError();return;}stopLive();$('video-title').textContent='Vídeo indisponível';$('video-message').textContent='Falha no player ('+(data.details||data.type||'HLS')+'). Clique em reconectar. Se persistir, consulte os logs do serviço video.';}});}else if(v.canPlayType('application/vnd.apple.mpegurl')){v.src=result.url;v.hidden=false;$('player-text').hidden=true;v.play().catch(()=>{});}else throw Error('Player HLS indisponível. Verifique internet para carregar a biblioteca do player.');}catch(e){if(generation!==playGeneration)return;$('video-title').textContent='Não foi possível abrir o vídeo';$('video-message').textContent=e.message;}}

async function removeCamera(id){const camera=cameras.find(c=>c.id===id);if(!camera)return;if(!confirm('Remover o dispositivo "'+camera.name+'"? O cadastro e suas credenciais serão excluídos. Esta ação será registrada na auditoria.'))return;try{const result=await api('/cameras/'+id,{method:'DELETE'});if(selected===id){stopLive();$('viewer').hidden=true;selected=null;}if(editing===id){$('device-form').elements.password.value='';$('device-dialog').close();editing=null;}await load();toast(result.gateway_cleaned?'Dispositivo removido.':'Cadastro removido; limpeza do gateway pendente. Reinicie o serviço video.');}catch(error){toast(error.message);}}
