$('organization-list').addEventListener('click',async e=>{const button=e.target.closest('button');if(!button)return;const sectorId=button.dataset.deleteSector,unitId=button.dataset.deleteUnit;if(!sectorId&&!unitId)return;const item=sectorId?sectors.find(x=>x.id===Number(sectorId)):units.find(x=>x.id===Number(unitId));if(!item||!confirm('Excluir '+(sectorId?'o setor ':'a unidade ')+item.name+'?'))return;button.disabled=true;try{await api((sectorId?'/sectors/':'/units/')+(sectorId||unitId),{method:'DELETE'});await reloadOrganization();$('organization-error').textContent='';toast('Cadastro excluído.');}catch(error){$('organization-error').textContent=error.message;button.disabled=false;}});

