function updateDeviceSelection(visible=filtered()){
 const allowed=new Set(visible.map(c=>c.id));
 for(const id of deviceSelection)if(!allowed.has(id))deviceSelection.delete(id);
 // Checkboxes were rendered before pruning; synchronize their current state.
 $('device-table').querySelectorAll('[data-select-device]').forEach(el=>el.checked=deviceSelection.has(Number(el.dataset.selectDevice)));
 $('device-selection-count').textContent=deviceSelection.size+' selecionadas';
 $('bulk-remove-devices').disabled=bulkRemoving||!deviceSelection.size;
 $('select-filtered-devices').disabled=bulkRemoving||!visible.length;
 $('clear-device-selection').disabled=bulkRemoving||!deviceSelection.size;
 const rows=visible.slice((devicePage-1)*50,devicePage*50);
 $('select-device-page').checked=!!rows.length&&rows.every(c=>deviceSelection.has(c.id));
 $('select-device-page').indeterminate=rows.some(c=>deviceSelection.has(c.id))&&!$('select-device-page').checked;
 $('select-device-page').disabled=bulkRemoving||!rows.length;
}
$('device-table').addEventListener('change',e=>{if(bulkRemoving||!e.target.matches('[data-select-device]'))return;const id=Number(e.target.dataset.selectDevice);if(e.target.checked)deviceSelection.add(id);else deviceSelection.delete(id);updateDeviceSelection();});
$('select-device-page').onchange=e=>{if(bulkRemoving)return;filtered().slice((devicePage-1)*50,devicePage*50).forEach(c=>e.target.checked?deviceSelection.add(c.id):deviceSelection.delete(c.id));render();};
$('select-filtered-devices').onclick=()=>{if(bulkRemoving)return;deviceSelection=new Set(filtered().map(c=>c.id));render();};
$('clear-device-selection').onclick=()=>{if(bulkRemoving)return;deviceSelection.clear();render();};
async function removeSelectedDevices(){
 if(bulkRemoving)return;
 const items=filtered().filter(c=>deviceSelection.has(c.id));if(!items.length)return;
 const summary=items.slice(0,10).map(c=>'• '+c.name).join('\n')+(items.length>10?'\n… e mais '+(items.length-10):'');
 if(!confirm('Excluir '+items.length+' dispositivos selecionados?\n\n'+summary+'\n\nOs cadastros e credenciais serão excluídos e cada remoção será registrada na auditoria. Esta ação não pode ser desfeita.'))return;
 bulkRemoving=true;render();$('bulk-remove-result').textContent='Iniciando remoção…';
 let removed=0,pendingGateway=0;const errors=[];
 try{
  for(let i=0;i<items.length;i++){
   const c=items[i];$('bulk-remove-result').textContent='Removendo '+(i+1)+' de '+items.length+'…';
   try{const result=await api('/cameras/'+c.id,{method:'DELETE'});removed++;if(!result.gateway_cleaned)pendingGateway++;deviceSelection.delete(c.id);cameras=cameras.filter(x=>x.id!==c.id);
    if(selected===c.id){stopLive();$('viewer').hidden=true;selected=null;}
    if(editing===c.id){$('device-form').elements.password.value='';$('device-dialog').close();editing=null;}
    if(positionCameraId===c.id)closePositioning();
   }catch(error){errors.push(c.name+': '+error.message);if(!authToken)break;}
  }
 }finally{bulkRemoving=false;await load();render();}
 const remaining=items.length-removed;
 $('bulk-remove-result').textContent=removed+' dispositivos removidos.'+(remaining?' '+remaining+' não removidos.':'')+(pendingGateway?' Limpeza de '+pendingGateway+' streams pendente; reinicie o serviço video.':'')+(errors.length?' '+errors.slice(0,5).join(' | '):'');
 toast(removed+' dispositivos removidos'+(remaining?' · '+remaining+' não removidos':''));
}
$('bulk-remove-devices').onclick=removeSelectedDevices;

let batchDiscoveryFingerprint=null,batchDiscoveryResult=null,batchDetecting=false;
function batchDiscoveryInput(){const f=$('batch-form').elements;const input={manufacturer:f.manufacturer.value,ip:f.ip.value.trim(),username:f.username.value,password:f.password.value,channels:channelsFrom(f.channels.value),management_port:Number($('batch-management-port').value),management_scheme:$('batch-management-scheme').value};if(!input.ip||!input.username||!input.password)throw Error('Preencha IP, usuário e senha do gravador.');if(!Number.isInteger(input.management_port)||input.management_port<1||input.management_port>65535)throw Error('Informe a porta web entre 1 e 65535.');return input;}
async function detectBatchChannels(){
 if(batchDetecting)throw Error('Aguarde a consulta em andamento.');
 const input=batchDiscoveryInput(),fingerprint=JSON.stringify(input);
 if(batchDiscoveryFingerprint===fingerprint&&batchDiscoveryResult)return batchDiscoveryResult;
 invalidatePreview('batch');batchDetecting=true;$('batch-detect').disabled=true;$('batch-validate').disabled=true;$('batch-discovery-message').textContent='Consultando cadastro de câmeras no gravador…';$('batch-discovery-reviewed').checked=false;
 try{
  const result=await api('/inventory/discover-channels',{method:'POST',body:JSON.stringify(input)});
  if(!$('batch-dialog').open||JSON.stringify(batchDiscoveryInput())!==fingerprint)throw Error('Os dados mudaram durante a consulta. Detecte novamente.');
  buildChannelFlags();let changed=false;
  for(const row of result.rows){const box=$('batch-channel-flags').querySelector('[data-channel="'+row.channel+'"]');if(box&&row.state!=='unknown'){const next=row.state==='free';if(box.checked!==next){box.checked=next;changed=true;}}}
  if(changed)invalidatePreview('batch');
  batchDiscoveryFingerprint=fingerprint;batchDiscoveryResult=result;
  $('batch-discovery-message').textContent=result.message;
  const labels={free:'Canal livre',configured:'Câmera cadastrada',unknown:'Revisão manual'};
  $('batch-discovery-results').innerHTML='<table><thead><tr><th>Canal</th><th>Cadastro</th><th>Detalhe</th></tr></thead><tbody>'+result.rows.map(r=>'<tr><td>'+r.channel+'</td><td>'+escapeText(labels[r.state])+'</td><td>'+escapeText(r.reason)+'</td></tr>').join('')+'</tbody></table>';
  $('batch-discovery-review-label').hidden=!result.rows.some(r=>r.state==='unknown');
  return result;
 }finally{batchDetecting=false;$('batch-detect').disabled=false;$('batch-validate').disabled=false;}
}
$('batch-detect').onclick=async()=>{try{batchDiscoveryFingerprint=null;batchDiscoveryResult=null;await detectBatchChannels();$('batch-error').textContent='';}catch(e){$('batch-error').textContent=e.message;}};
const validateBatchWithDiscovery=validateBatch;
validateBatch=async function(e){e.preventDefault();if(batchDetecting)return;try{if($('batch-auto-detect').checked){const result=await detectBatchChannels();if(result.rows.some(r=>r.state==='unknown')&&!$('batch-discovery-reviewed').checked){invalidatePreview('batch');throw Error('Revise os canais inconclusivos e marque a confirmação de revisão manual antes de validar.');}}await validateBatchWithDiscovery(e);}catch(error){$('batch-error').textContent=error.message;}};
$('batch-form').onsubmit=validateBatch;
$('batch-dialog').addEventListener('close',()=>{batchDiscoveryFingerprint=null;batchDiscoveryResult=null;$('batch-discovery-results').innerHTML='';$('batch-discovery-message').textContent='';$('batch-discovery-review-label').hidden=true;$('batch-discovery-reviewed').checked=false;});

function unitLocationCount(){const f=$('unit-location-form'),u=units.find(x=>x.id===Number(f.elements.unit_id.value));if(!u)return 0;const scope=f.elements.camera_scope.value;return cameras.filter(c=>c.unit_id===u.id&&(scope==='all'||scope==='center'&&Math.abs(c.lat-u.lat)<=0.000001&&Math.abs(c.lng-u.lng)<=0.000001)).length;}
function showUnitLocationCount(){$('unit-location-count').textContent=unitLocationCount()+' câmeras terão a posição atualizada, incluindo canais livres que correspondam à opção escolhida.';}
$('organization-list').addEventListener('click',e=>{const b=e.target.closest('[data-location-unit]');if(!b)return;const u=units.find(x=>x.id===Number(b.dataset.locationUnit));if(!u)return;const f=$('unit-location-form');f.reset();f.elements.unit_id.value=u.id;f.elements.lat.value=u.lat;f.elements.lng.value=u.lng;$('unit-location-title').textContent='Editar localização — '+u.name;f.hidden=false;showUnitLocationCount();f.scrollIntoView({behavior:'smooth',block:'center'});});
$('unit-location-form').elements.camera_scope.onchange=showUnitLocationCount;
$('cancel-unit-location').onclick=()=>$('unit-location-form').hidden=true;
$('unit-location-form').onsubmit=async e=>{e.preventDefault();const f=e.target,id=Number(f.elements.unit_id.value),body={lat:Number(f.elements.lat.value),lng:Number(f.elements.lng.value),camera_scope:f.elements.camera_scope.value};if(!confirm('Salvar o centro da filial em '+body.lat+', '+body.lng+' e atualizar a posição de '+unitLocationCount()+' câmeras?'))return;const b=f.querySelector('[type="submit"]');b.disabled=true;try{const r=await api('/units/'+id+'/location',{method:'PATCH',body:JSON.stringify(body)});cameras=await api('/cameras');await reloadOrganization();f.hidden=true;$('organization-error').textContent='';toast('Localização salva. '+r.updated_cameras+' câmeras atualizadas.');}catch(error){$('organization-error').textContent=error.message;}finally{b.disabled=false;}};

function renderCameraDetails(c){const playing=liveReceivingId===c.id&&Date.now()-lastVideoProgress<5000;const indicator=c.status;$('viewer-title').textContent=c.name;$('viewer-status').innerHTML='<i class="dot '+(indicator==='online'?'online':indicator==='offline'?'offline':'unknown')+'"></i>';$('viewer-status').setAttribute('aria-label',playing?'Vídeo recebido agora · monitor: '+(names[c.status]||'Não verificada'):(names[c.status]||'Não verificada'));$('viewer-status').title=playing?'Vídeo recebido agora · monitor: '+(names[c.status]||'Não verificada'):(names[c.status]||'Não verificada');$('viewer-info').textContent='Unidade: '+(c.unit_name||'Unidade não informada');$('viewer-id').textContent='Id: '+c.id;$('viewer-details').innerHTML=[['Latitude',Number(c.lat).toFixed(11)],['Longitude',Number(c.lng).toFixed(11)],['Setor',c.sector_name||'Sem setor']].map(([label,value])=>'<div><dt>'+escapeText(label)+': </dt><dd>'+escapeText(String(value))+'</dd></div>').join('');$('viewer-checked').textContent='';$('viewer-diagnostic').textContent=c.diagnostic||'';}
$('retry-live').onclick=()=>{if(selected)startLive(selected);};

async function openReadyLive(id,generation){
 const canceled=()=>generation!==playGeneration;const deadline=Date.now()+45000;
 const request=async(path,options,timeout)=>{const controller=new AbortController();liveAbort=controller;const timer=setTimeout(()=>controller.abort(),timeout);try{return await fetch(path,{...options,signal:controller.signal,cache:'no-store'});}finally{clearTimeout(timer);if(liveAbort===controller)liveAbort=null;}};
 const ticket=async()=>{const r=await request('/api/cameras/'+id+'/live',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+authToken,'X-Video-Client':videoClientKey}},Math.max(1,Math.min(40000,deadline-Date.now())));const data=await r.json();if(!r.ok){const e=Error(data.detail||'Falha ao preparar vídeo.');e.status=r.status;throw e;}return data;};
 let result=await ticket();if(canceled())return;
 let failures=0,renewals=0,lastMessage='';
 while(Date.now()<deadline&&!canceled()){
  $('video-title').textContent='Preparando vídeo…';$('video-message').textContent='Aguardando o gravador'+(result.converted?' e a conversão':'')+'. A imagem abrirá automaticamente.';
  try{
   const r=await request(result.url,{},Math.min(30000,deadline-Date.now()));if(canceled())return;
   if(r.ok){const body=await r.text();if(body.trimStart().startsWith('#EXTM3U'))return result;}
   else{const data=await r.json().catch(()=>({}));lastMessage=data.detail||'';if([401,403,409,422,429].includes(r.status)){const e=Error(lastMessage||'Abertura não autorizada.');e.status=r.status;throw e;}if(/autenticação|permissão|codificador|opção FFmpeg/i.test(lastMessage)){const e=Error(lastMessage);e.status=422;throw e;}}
  }catch(e){if(canceled())return;if(e.status)throw e;}
  failures++;
  if(failures>=3&&renewals<2&&deadline-Date.now()>5000){result=await ticket();if(canceled())return;renewals++;failures=0;}
  if(Date.now()<deadline)await new Promise(resolve=>setTimeout(resolve,Math.min(2000,deadline-Date.now())));
 }
 if(!canceled())throw Error('O vídeo não ficou disponível dentro de 45 segundos. '+(lastMessage||'Verifique o stream e os logs de video e app.'));
}

function volumeIcon(muted){return '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4z"/>'+(muted?'<path d="m16 9 5 6m0-6-5 6"/>':'<path d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>')+'</svg>';}
function updateVolumeIcon(){const muted=$('live-video').muted,b=$('reference-mute');b.innerHTML=volumeIcon(muted);b.title=muted?'Ativar áudio':'Silenciar áudio';b.setAttribute('aria-label',b.title);b.setAttribute('aria-pressed',String(!muted));}
$('reference-mute').onclick=()=>{const v=$('live-video');v.muted=!v.muted;updateVolumeIcon();};
$('live-video').addEventListener('volumechange',updateVolumeIcon);updateVolumeIcon();
$('player-panel').ondblclick=()=>$('fullscreen').click();

let recorderSettingsId=null;
$('configure-recorder-state').onclick=async()=>{if(!editing){toast('Salve primeiro o cadastro do gravador.');return;}const c=cameras.find(x=>x.id===editing);if(!['Intelbras','Hikvision'].includes(c?.manufacturer)||c?.device_type!=='nvr'){toast('Disponível para gravadores Intelbras e Hikvision.');return;}try{const r=await api('/cameras/'+editing+'/recorder-status');recorderSettingsId=editing;const f=$('recorder-state-form');f.elements.enabled.checked=r.enabled;f.elements.web_port.value=r.web_port;f.elements.scheme.value=r.scheme;$('recorder-state-error').textContent='';$('recorder-state-dialog').showModal();}catch(e){toast(e.message);}};
$('close-recorder-state').onclick=()=>$('recorder-state-dialog').close();
$('recorder-state-form').onsubmit=async e=>{e.preventDefault();const f=e.target;try{await api('/cameras/'+recorderSettingsId+'/recorder-status',{method:'PUT',body:JSON.stringify({enabled:f.elements.enabled.checked,web_port:Number(f.elements.web_port.value),scheme:f.elements.scheme.value})});$('recorder-state-dialog').close();toast('Consulta configurada para este gravador. Os estados serão atualizados no próximo ciclo.');}catch(error){$('recorder-state-error').textContent=error.message;}};

$('live-video').addEventListener('timeupdate',()=>{const v=$('live-video');if(!v.hidden&&v.currentTime!==lastVideoTime){lastVideoTime=v.currentTime;lastVideoProgress=Date.now();liveReceivingId=selected;const c=cameras.find(x=>x.id===selected);if(c)renderCameraDetails(c);confirmLivePlayback();}});

setInterval(()=>{if(liveReceivingId&&Date.now()-lastVideoProgress>=5000){liveReceivingId=null;const c=cameras.find(x=>x.id===selected);if(c)renderCameraDetails(c);}},1000);

async function confirmLivePlayback(){
 const video=$('live-video');
 if(!activeLiveTicket||liveConfirming||video.paused||video.readyState<2||Date.now()-lastLiveConfirmation<30000)return;
 const ticket=activeLiveTicket,generation=playGeneration,id=selected;
 liveConfirming=true;lastLiveConfirmation=Date.now();
 try{
  const result=await api('/live-confirm',{method:'POST',headers:{'X-Video-Client':videoClientKey},body:JSON.stringify({ticket})});
  if(generation!==playGeneration||ticket!==activeLiveTicket||id!==selected)return;
  if(result.confirmed&&result.camera_id===id){
   const camera=cameras.find(c=>c.id===id);
   if(camera){camera.status=result.status;camera.checked_at=result.checked_at;camera.verification_stale=false;camera.diagnostic=result.diagnostic;render();}
   await load();
  }
 }catch(error){if(generation===playGeneration&&error.status===409)activeLiveTicket=null;}
 finally{liveConfirming=false;}
}
